node.doctext:
[https://perldoc.perl.org/Memoize.html|Memoize] one of the most under utilized modules Perl has to offer for speeding things up.<br>
Look for comment "# Uncomment the three lines below to speed things up" to test [https://perldoc.perl.org/Memoize.html|Memoize].<br><br>
<c>#!/usr/bin/perl
use strict;
use warnings;
use Carp qw(carp croak);
use Data::Dumper;
use Benchmark;

my %loaded;
for (qw/ Digest::MD5 /) {
    eval "use $_";
    unless ($@) {
        $loaded{$_} = $_->VERSION;
    }
}
print "Benchmarking...\n";
for my $key (sort keys %loaded) {
    print "$key\t$loaded{$key}\n";
}

my $code = <<'EOM';
[b]bold [i]italic[/i] test[/b]
[code]some [perl] code[/code]
[url=http://foo.example.org/]a link![/url]

EOM

sub Dmd5 {
    my $pb = Digest::MD5->new;
   # Uncomment the three lines below to speed things up
   # use Memoize;
   # memoize('Digest::MD5::add');
   # memoize('Digest::MD5::hexdigest');
    return $pb;
}

my ($pb);
if ($loaded{'Digest::MD5'}) {
    $pb = Dmd5();
    my $rendered1 = $pb->add($code);
}

timethese($ARGV[0] || -1, {
    $loaded{'Digest::MD5'} ?  (
        'Digest::MD5::new'  => \&Dmd5,
        'Digest::MD5'  => sub { my $out = $pb->hexdigest },
    ) : (),
});

#Benchmarking...
#Digest::MD5	2.55
#Benchmark: running Digest::MD5, Digest::MD5::new for at least 1 CPU seconds...
#Digest::MD5: -1 wallclock secs ( 1.11 usr +  0.00 sys =  1.11 CPU) @ 138871.96/s (n=154009)
#Digest::MD5::new:  1 wallclock secs ( 1.11 usr +  0.00 sys =  1.11 CPU) @ 69872.97/s (n=77559)
#
#Benchmarking with Memoize...
#Digest::MD5	2.55
#Benchmark: running Digest::MD5, Digest::MD5::new for at least 1 CPU seconds...
#Digest::MD5:  1 wallclock secs ( 1.12 usr +  0.00 sys =  1.12 CPU) @ 61895.11/s (n=69632)
#Digest::MD5::new:  1 wallclock secs ( 1.06 usr +  0.03 sys =  1.09 CPU) @ 5227.61/s (n=5719)
</c>
